import pathlib
import sys

lines = sys.stdin.read().splitlines()
if not lines or lines[0] != '*** Begin Patch' or lines[-1] != '*** End Patch':
    raise SystemExit('invalid patch envelope')
index = 1
while index < len(lines) - 1:
    header = lines[index]
    if header.startswith('*** Add File: '):
        path = pathlib.Path(header[len('*** Add File: '):])
        index += 1
        content = []
        while index < len(lines) - 1 and not lines[index].startswith('*** '):
            line = lines[index]
            if not line.startswith('+'):
                raise SystemExit(f'malformed add line: {line}')
            content.append(line[1:])
            index += 1
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text('\n'.join(content) + '\n')
        continue
    if not header.startswith('*** Update File: '):
        raise SystemExit(f'unsupported patch operation: {header}')
    path = pathlib.Path(header[len('*** Update File: '):])
    content = path.read_text().splitlines()
    index += 1
    cursor = 0
    while index < len(lines) - 1 and not lines[index].startswith('*** '):
        if not lines[index].startswith('@@'):
            raise SystemExit(f'expected hunk, got: {lines[index]}')
        index += 1
        old = []
        new = []
        while index < len(lines) - 1 and not lines[index].startswith('@@') and not lines[index].startswith('*** '):
            line = lines[index]
            if not line:
                raise SystemExit('malformed patch line')
            prefix, text = line[0], line[1:]
            if prefix in ' -':
                old.append(text)
            if prefix in ' +':
                new.append(text)
            index += 1
        found = -1
        for candidate in range(cursor, len(content) - len(old) + 1):
            if content[candidate:candidate + len(old)] == old:
                found = candidate
                break
        if found < 0:
            raise SystemExit(f'hunk not found in {path}: {old[:3]}')
        content[found:found + len(old)] = new
        cursor = found + len(new)
    path.write_text('\n'.join(content) + '\n')
